/** Справка относится только к наблюдателю. Открытие не расходует RNG, не меняет
 * геном и не добавляет знаний жителям. Тексты хранятся централизованно, чтобы
 * у одинаковых настроек обычной игры и испытаний был одинаковый смысл.
 * Нативный dialog открывается кликом/Enter/Space, удерживает фокус и закрывается
 * Escape. Поэтому помощь доступна на телефоне и с клавиатуры, без hover.
 */
export const HELP={
 'compute-workers':['Вычислители','Настройка следующего нового опыта: авто,1,2 или4. Один — прежний последовательный расчёт. При2/4 общая физика остаётся у координатора, личные мозги и память считаются параллельно. Авто выбирает1 для старта меньше32 особей или устройства с менее4 логическими CPU, иначе2…4. Число потоков не меняет правила или порядок случайных выборов.'],
 'performance-mode':['Режим измерений','Лёгкий режим записывает полные шаги, границы задач и промежутки с меньшими накладными расходами. Подробный также разбирает этапы каждого десятого шага. Выбор действует на новую запись; во время записи он недоступен. Оба режима измеряют прошедшее время, а не загрузку CPU.'],
 'performance-start':['Измерение скорости','Записывает 30 активных секунд основного мира, завершая текущий шаг. Не запускает мир: нажми «Наблюдать», если он на паузе. Лёгкий режим учитывает полные шаги, задачи и промежутки; подробный также разбирает каждый десятый шаг. Интерфейс измеряется отдельно. Это прошедшее время, не процент загрузки CPU; GC и планирование ОС требуют внешней трассы. Повторная запись заменяет предыдущую.'],
 'performance-stop':['Завершить измерение','Останавливает только запись времени. Мир продолжает работать. Паузы исключаются из активного интервала; одиночные шаги на паузе учитываются во времени расчёта, но скорость в таком режиме не показательна.'],
 'performance-export':['Скачать профиль','Скачивает компактный JSON времён, численности, настроек, сборки и ограничений измерения. Завершает запись, не останавливая мир. Для разбора скорости пришли этот файл; обычные наблюдения мира тоже содержат последний профиль.'],
 'benchmark-start':['Постоянные замеры','Выбери версии и от1 до100 повторов на группу (по умолчанию оценщики50, миры15). Шесть нагрузок и чередование версий. Мир0.32 последовательный, мир0.33 использует4 владельца личного опыта; оценки мозга последовательные. Прогрев отдельно, опыт сбрасывается. Подготовка, полные снимки, хеширование и уступки очереди вне computeMs; обмен и барьеры внутри параллельного шага включены. Миры проходят64 шага; оценки —4096 пакетов. Это замер скорости, не отбор геномов. Основной мир одновременно не запускается.'],
 'benchmark-group-evaluator':['Замер оценщиков','Три фиксированных набора оценки действий без исполнения мира. Галочка включает их в выбранные замеры. Число повторов независимо от миров.'],
 'benchmark-group-world':['Замер миров','Три полноценных мира: 150, 400 и 1000 основателей. В каждом повторе 64 шага, память и обучение включены. Галочка включает эту группу.'],
 'benchmark-repeats-evaluator':['Повторы оценщиков','1…100 повторов каждой оценочной нагрузки на каждую выбранную версию. По умолчанию 50. Выключенная группа не запускается.'],
 'benchmark-repeats-world':['Повторы миров','1…100 повторов каждого фиксированного мира на каждую выбранную версию. По умолчанию 15. Это повтор одинаковых условий, не новые seed.'],
 'randomize-seed':['Случайный номер опыта','Выбрать новый случайный номер из энтропии браузера. Меняется только поле стартовых условий. Мир изменится после «Начать новый опыт». Генератор мира не расходуется.'],
 'benchmark-stop':['Остановить замеры','Worker завершает текущий пакет и возвращает уже завершённые повторы. Неполный запуск нельзя использовать для сравнения ускорения. На тяжёлом устройстве остановка может потребовать времени.'],
 'benchmark-export':['Скачать замеры','Скачивает небольшой JSON с отпечатками начальных/итоговых состояний и всеми измеренными повторами. Сами миры и геномы в этом отчёте не сохраняются. После обновления сайта загрузи прежний JSON для сравнения.'],
 'benchmark-previous':['Прошлый замер','Загружает отдельный JSON постоянных замеров или извлекает их из общего отчёта лаборатории. Сравнение требует одинаковых нагрузок, стартовых и итоговых состояний, числа действий. Изменение устройства или фоновой нагрузки делает вывод об ускорении ненадёжным. Обычный профиль производительности не подходит.'],
 play:['Наблюдать / пауза','Запускает или приостанавливает шаги текущего мира. Пауза не сбрасывает геномы и опыт. После вымирания нужен новый запуск.'],
 step:['Один шаг','Приостанавливает наблюдение и выполняет один шаг мира: восстановление пищи, действия жителей, пищеварение, повреждения и рождения. Шаг — условная единица, не год.'],
 speed:['Темп наблюдения','Множитель частоты шагов: 1× соответствует цели 10 шагов/с. Если устройство не успевает, фактическая скорость ниже. Ускорение не меняет стоимость действий или правила шага. В испытаниях миры считаются без отрисовки на доступной скорости.'],
 seed:['Номер опыта (seed)','Число задаёт повторяемую случайность карты и начальных геномов. Одинаковые seed и настройки воспроизводят опыт. После изменения поведения потоки событий разных режимов могут расходиться. Жители seed не знают.'],
 founders:['Основатели','Сколько организмов появляется в начале. Они начинают без личных воспоминаний. Обычно геномы случайны; загруженная основа меняет этот старт. Это не число жителей, которое мир обязан поддерживать.'],
 geography:['География и старт','По умолчанию — реки/озёра и пространственно равномерное размещение по всей суше. До 20% карты занято водой, броды проходимы как суша. Места основателей не подбираются к еде; их число распределяется по участкам пропорционально суше. Прежние профили оставлены в технических проверках, из пользовательского выбора убраны. Один seed сохраняет исходные гены при смене профиля. География применяется при новом опыте; текущую воду этот выбор не меняет. Обзор жителя остаётся радиусом 1.'],
 'geography-region':['Рельеф и районы','Сведения наблюдателя: вариант карты/старта, доля воды, число рек/озёр/бродов и связных сухих районов. Вода блокирует шаг; брод — проходимый сухой разрыв с прежней стоимостью шага. Районы могут быть изолированы, пища в другом районе не обязательно доступна жителю. Мозг получает только текущий гекс/соседей и свою память, номера районов и карта ему не передаются. Опасная область пока остаётся на прежних координатах.'],
 'population-limit':['Лимит живых','Вычислительный предел численности. При его достижении рождения блокируются; живые не удаляются. Лимит может влиять на отбор, поэтому он сохраняется в отчёте.'],
 'food-islands':['Количество островков','Число основных групп, 1…384, по умолчанию 8. Общее число источников сохраняется: больше островков означает меньшие группы. Около 20% бюджета оставляется одиночным кустам; при недостатке источников их доля снижается, затем число групп ограничивается числом источников. При нуле источников групп нет.'],
 'food-period-spread':['Разброс периодов','0…90% относительно центрального периода, по умолчанию ±30%. Каждый островок и куст получает своё случайное значение, округлённое до целых шагов и ограниченное 10…1600. Значение и случайная фаза сохраняются до изменения среды. При 0% периоды равны, но фазы различаются. Расписание скрыто от жителей.'],
 'food-size-spread':['Разброс размеров','0…90%, по умолчанию 30%. Меняет случайные веса распределения источников между островками. После нормировки и округления сумма точно равна общему бюджету за вычетом одиночных кустов. При 0% размеры отличаются максимум на один источник. Это число источников, не радиус круга; вода исключена. Изменение разброса размеров перераспределяет источники.'],
 'food-sources':['Количество источников','Точное число клеток, производящих пищу: 0…384. Они сгруппированы в островки; источник и островок — разные вещи. Ёмкость клетки 3–6 порций, в начале она заполнена. Меньше источников уменьшает начальный запас и потенциальное производство; Около 20% клеток — одиночные кусты, остальные распределяются по заданному числу островков. Увеличение числа островков при том же бюджете уменьшает их средний размер. При нуле пищи популяция всё равно появляется и может вымереть. Применяется при новом запуске.'],
 'food-period':['Период восстановления','Число шагов между пополнениями, 10…1600, по умолчанию 20. Это центральное значение для индивидуальных периодов островков и кустов. Их разброс задаётся отдельно; каждая группа получает случайную фазу и плодоносит по своему расписанию. На событии каждый неполный источник группы получает одну порцию. Полный источник пропускает событие, не копит долг. Больше период — меньше производство новой пищи; при одинаковом seed начальные запасы, геномы и позиции сохраняются. Медленная пища может вызывать переходы, ожидание или вымирание; обязательной миграции нет. Применяется при новом запуске.'],
 'upgrade-mutations':['Преобразовать старый геном','При следующем новом опыте добавляет два наследуемых регулятора мутаций. Мозг и прежние гены сохраняются. Одна повторяемая случайная пара для всех основателей. Без этой галочки импорт остаётся прежним.'],
 'tests-upgrade-mutations':['Преобразование основы испытаний','Явно добавляет наследуемую изменчивость загруженной основе каждого нового мира. Старый мозг не заменяется, личный опыт не переносится. При снятой галочке старый файл не расширяется.'],
 'mutation-rate':['Мутации старой основы','Общая вероятность только для старого генома без явного преобразования. Новые случайные основатели используют собственные наследуемые вероятность и силу; это поле их не меняет. Вероятность изменения каждого прежнего наследуемого числа при рождении. Общие свойства мозга мутируют в четыре раза реже и меньшими изменениями. Мутации не являются обучением и не изменяют геном живого родителя.'],
 learning:['Личное обучение (TD)','Включает изменение личных оценок действий по последствиям и ожиданиям. TD означает «временная разность»: сравнение ожидаемого и полученного результата. Опыт не наследуется. Обучение не гарантирует лучшего поведения; его надо сравнивать на одинаковых стартах.'],
 memory:['Память мест','Позволяет сохранять собственные наблюдения и закреплять важные места. Мировая карта не открывается. Память работает и без TD; при выключенной памяти локальное TD-обучение всё ещё возможно. Вместимость и забывание зависят от генов.'],
 mutations:['Мутации у потомков','Если выключить, потомки получают неизменённый геном родителя. При этом разные исходные геномы могут отбираться, а личное обучение продолжает работать, если включено.'],
 'load-genome':['Геном как основа','Геном v12 — 1463 наследуемых числа: основной и малый мозг, свойства и изменчивость. Старые геномы не запускают новую модель. Файл задаёт основу новых основателей после перезапуска. Не загружает воспоминания, тело или прежний мир. Основной сценарий игры — случайные геномы с нуля.'],
 'expand-legacy':['Дополнение старого генома','Только для основы версии 1: добавляет одну общую случайную часть новых свойств для всех основателей. Без галочки добавленные числа нулевые. Прежние 435 значений сохраняют смысл, их индексы преобразованы под 10 действий; добавка повторяется по seed.'],
 'clear-base':['Случайные геномы','Убирает загруженную основу из настроек следующего запуска. Чтобы создать новую случайную популяцию в обычной игре, затем нажми «Начать новый опыт».'],
 restart:['Начать новый опыт','Создаёт новый мир с текущими настройками и пустым опытом основателей. Истории текущего мира сбрасываются. Скачай нужные результаты заранее. Простое изменение настройки уже запущенный мир не меняет.'],
 'save-genome':['Сохранить геном','Скачивает наследственные числа выбранного организма и сведения об их происхождении. Не сохраняет его личный опыт. Геном выбранного умершего доступен, пока его объект выбран; произвольные строки истории пока не хранят все геномы.'],
 'next-agent':['Следующий житель','Выбирает следующего живого жителя для наблюдения. Выбор не управляет его действиями. Жителя также можно выбрать нажатием на карте.'],
 'show-memory':['Обводки памяти','Показывает места из памяти выбранного жителя на карте наблюдателя. Толстая обводка — закреплённое место, тонкая — краткая запись; жёлтая означает ранее увиденную пищу. Увиденная ранее еда не обязательно есть там сейчас.'],
 'rules-open':['Правила мира','Открывает физические правила текущей версии: пища, энергия, длительности и размножение. Это заданные условия модели; жители не получают этот текст.'],
 'rules-close':['Вернуться','Закрывает описание правил. Мир остаётся на паузе; продолжение наблюдения выбираешь ты.'],
 'history-export':['Скачать истории','Сохраняет JSON с итогами текущих жизней и условиями мира. Возраст живых — незавершённое наблюдение, а не возраст смерти. Файл не является сохранением для продолжения мира.'],
 'history-filter':['Фильтр жизней','Показывает живых, умерших или завершённые жизни с выбранной причиной гибели. Фильтр меняет только таблицу, а не общую статистику мира.'],
 'history-sort':['Порядок строк','Сортирует видимые жизни по номеру, возрасту или числу детей. Число детей пока не означает число выживших взрослых потомков.'],
 'history-search':['Поиск жителя или линии','Показывает совпадения по номеру жителя или номеру линии основателя. Пустое поле не ограничивает выборку.'],
 'history-prev':['Страницы истории','Переключает таблицу по 100 строк на страницу. Скрытые на другой странице записи не удаляются.'],
 'test-seeds':['Seed испытаний','Разные номера создают независимые миры. Для каждого номера выбранные режимы мозга начинают с одинаковых исходных условий при выбранных пищевых параметрах. Допустимы 1…64 различных номера.'],
 'test-steps':['Длительность испытания','Максимальное число шагов каждого мира. Вымирание завершает мир раньше. Доживший мир наблюдался до этого срока; его полный срок существования неизвестен.'],
 'test-parallel':['Параллельные миры','Количество независимых Workers, считающихся одновременно, от 1 до 12. Больше не всегда быстрее: ограничивают процессор и память. Это не несколько потоков расчёта одной популяции.'],
 'mode-no-memory-no-td':['Без памяти и TD','Контроль: геном и текущие локальные наблюдения влияют на выбор, но приобретённая память мест и личные TD-оценки выключены. Мутации и отбор могут продолжаться.'],
 'mode-memory-only':['Память без TD','Организм запоминает и закрепляет наблюдения, использует их согласно наследуемым склонностям. Личный TD-критик не меняет оценки. Это отделяет пространственную память от дополнительного обучения действиям.'],
 'mode-memory-and-td':['Память и TD','Одновременно работают личная память и обучение оценок действий. Дополнительная сложность не гарантирует преимущество: сравнивай выживание, возраст и потомство по одинаковым seed.'],
 'test-save-genomes':['Контрольные геномы','Сохраняет образцы по возрасту, числу детей и поколению на контрольных моментах. Это не все геномы мира и не доказательство «лучшего организма». Увеличивает размер JSON.'],
 'tests-base-file':['Основа испытаний','Необязательный геном для одинаковых начальных основателей. Для отделения личного опыта от генетических изменений можно также выключить мутации. Память и опыт начинают с нуля в каждом мире.'],
 'tests-clear-base':['Случайный старт испытаний','Убирает основу из следующего пакета испытаний. Уже считающиеся миры остаются с прежними настройками.'],
 'run-checks':['Проверки механизмов','Запускает изолированные проверяемые ситуации в Worker на твоём устройстве. «Пройдено» относится к механике, а не к успеху эволюции. Отображение интерфейса этими проверками не проверяется.'],
 'run-experiments':['Длинные испытания','Запускает отдельные миры без карты. Предыдущий отчёт заменяется; скачай его заранее. Вымирание — результат опыта, ошибка баланса или некорректное тело — ошибка механики. Оставь вкладку браузера открытой.'],
 'tests-stop':['Остановить и собрать итоги','Просит работающие миры остановиться и вернуть текущую статистику; задания в очереди не запускаются. Незавершённые миры не выдаются за полные испытания.'],
 'tests-force-stop':['Прервать немедленно','Завершает Workers сразу. Сохраняет уже полученные итоги и последний прогресс; полных итогов активных миров может не быть.'],
 'tests-export':['Скачать весь отчёт','Один JSON объединяет последние результаты механизмов, замеров скорости и длинных испытаний. Незапущенные разделы отсутствуют; ошибки и прерванные результаты сохраняются со статусом. Каждый раздел хранит свою версию, сборку и настройки. Новый запуск одного раздела не затирает другие. Экспорт текущего запуска неполный — для полного результата дождись окончания. Файл не продолжает живые миры.'],
 population:['Живые','Текущая численность. Уменьшение может означать голод или достижение предела возраста; смотри причины и истории.'],
 'test-reproduction':['Размножение в испытаниях','Обычная игра: выбор при энергии ≥50 и здоровье ≥40. Контрольные варианты: выбор 86/55 и выбор 50/55. Автоматического режима в новых испытаниях нет. Сравнивай их последовательно на тех же seed и пищевых условиях: так отделяются выбор и два порога. Все новые варианты используют длительные роды и текущую модель.'],
 'reproduction-summary':['Возможность и выбор рождения','Счётчики по реальным решениям, включая умерших: мог родить, выбрал и состоявшиеся рождения. Причины недоступности считаются независимо и могут совпадать; их сумма не равна числу решений. Просмотр панели не добавляет решений.'],
 'reproduction-status':['Размножение выбранного жителя','Рождение — вариант политики при энергии ≥50, здоровье ≥40, возрасте ≥90 и интервале ≥100, если лимит допускает. Роды занимают20 подшагов и блокируют другие действия. В конце32 энергии: ребёнку28, расход4. Лимит проверяется при начале; смерть отменяет рождение. Нет обязательного рождения или отдельного удовольствия за него. «Мог» измеряется после пищеварения перед действием, текущая доступность — состояние сейчас.'],
 births:['Рождения','Все рождения после начала опыта. Основатели сюда не входят. Рождение само по себе не означает, что потомок долго прожил.'],
 deaths:['Гибели','Число завершённых жизней текущего мира, независимо от причины. Живые сюда не входят.'],
 generation:['Максимальное поколение','Наибольшая глубина родословной, достигнутая с начала мира. Основатели имеют поколение 0. Это не уровень интеллекта и не текущий возраст популяции.'],
 lineages:['Линий осталось','Сколько основателей представлено среди ныне живых потомков. Одна оставшаяся линия может включать разные мутировавшие геномы.'],
 'feeling-mean':['Среднее самочувствие','Внутренняя оценка −100…+100 с наследуемыми знаками чувствительности. −15 не означает 15% голода или здоровья. Между разными геномами это не общая шкала благополучия; смотри также энергию, здоровье, длительность жизни и потомство.'],
 'food-region':['Пищевые условия и близость','Показывает реальные настройки нынешнего мира. Их меняет панель «Изменить текущий мир»; отдельные условия нового опыта применяются при перезапуске. Близость — счётчик наблюдателя: живые не дальше трёх гексов от действующего источника, даже если он пуст. Лежащая еда на бывшем источнике сюда не входит. Показатель не передаётся мозгу. Концентрация может возникнуть от отбора или опыта; одна карта не доказывает обучение.'],
 'world-food-current':['Условия продолжающегося мира','Действующие источники, их ёмкости, период и следующий срок восстановления. Еда вне источников доступна для сбора, но здесь больше не растёт. На карте она обведена пунктиром. Шаги мира и часы компьютера различны: на паузе ничего не восстанавливается.'],
 'world-food-sources':['Изменить число источников','От 0 до 384 производящих клеток в этом же мире. Изменение количества пересоздаёт раскладку с текущими настройками островков. Места выбираются независимо от жителей. Лежащая еда сохраняется на каждой клетке; новый источник не получает подаренного стартового запаса. Ноль отключает производство, но позволяет доесть всё оставшееся. Ползунок сам по себе ничего не меняет: нажми «Применить».'],
 'world-food-period':['Изменить восстановление','От 10 до 1600 шагов между пополнениями одной порцией. После фактического изменения условий группы получают периоды и новые случайные фазы от шага вмешательства. Первое пополнение может наступить через 1…period шагов; накопленная еда сохраняется. Изменение только периода/его разброса не переносит источники. Полные источники и источники с избытком еды пропускают пополнение. Применение совпадающих условий сохраняет прежний цикл. Период не раскрывается жителям.'],
 'world-food-fixed-capacity':['Одинаковая ёмкость','Включи для назначения одной ёмкости всем действующим источникам. Без галочки ёмкости оставшихся сохраняются, у новых обычные 3…6. Изменение ёмкости не создаёт и не удаляет порции. Если еды больше новой ёмкости, её можно доесть, а восстановление возобновится после снижения запаса ниже ёмкости.'],
 'world-food-capacity':['Ёмкость источника','От 1 до 24 порций на клетку. Это предел восстановления, а не вместимость инвентаря или желудка. Большая ёмкость позволяет источнику накопить больше еды со временем. Ползунок действует вместе с галочкой одинаковой ёмкости после применения.'],
 'world-food-relocate':['Перераспределение','При применении создаёт новую раскладку источников островками по всей суше. Количество и ёмкости определяют соседние настройки. Еда остаётся на прежних клетках; могут возникнуть запасы без восстановления. Места выбираются независимо от расположения жителей. Их старая память сохраняется и пересматривается только при собственных наблюдениях; сообщения о скрытой перестановке они не получают.'],
 'world-food-apply':['Применить к текущему миру','Меняет производство пищи между целыми шагами. Работающий мир продолжает работу, приостановленный остаётся на паузе. Шаг, тела, геномы, личный опыт и родословные сохраняются. Остальные настройки ниже и отдельные испытания не меняются. Вымершая популяция не возрождается от изменения пищи.'],
 'world-food-export':['Скачать наблюдения','JSON содержит исходные и нынешние пищевые условия, весь журнал вмешательств с шагами и накопительными итогами, статистику, истории жизней и последние 800 точек графика. Его можно прислать для анализа. Это не полное сохранение для продолжения мира и не требует сохранения геномов.'],
 'action-title':['Вероятности действий','Действие «Положить» доступно при еде в инвентаре и запасе менее 10 на текущей суше. Геном, нынешние наблюдения и приобретённые оценки превращаются в вероятности допустимых действий. Число 70% не означает осознанный план. Направления относятся к собственному взгляду, а не к сторонам мировой карты.'],
 'memory-summary':['Два уровня памяти','Краткая память хранит недавние наблюдения; долгая — закреплённые места. Повторные возвращения, сильные или неожиданные ощущения могут закреплять записи. Новое наблюдение пересматривает сведения; уверенность и значимость стареют. Вместимость ограничена.'],
 'metric-energy':['Энергия','Запас тела 0…100. Пищеварение восполняет его, действия расходуют: ожидание 0.30, положить 0.36, шаг 0.78, подбор 0.66, поедание 0.48 за единицу времени. Предельный возраст — 10 000 шагов. При нулевой энергии начинается потеря здоровья. Избыток при насыщении теряется.'],
 'metric-health':['Здоровье','Состояние тела 0…100. Повреждения и длительное отсутствие энергии снижают здоровье. Сейчас заживления нет; нулевое здоровье приводит к гибели.'],
 'metric-pain':['Боль','Возникает при повреждении и постепенно затухает. Уменьшение боли не восстанавливает здоровье. Неприятность боли зависит от наследуемой чувствительности, её знак не принудительно задан.'],
 'metric-position':['Личная позиция','Начинается с (0, 0) при рождении, считает собственные перемещения. Это не мировые x/y. Пока счёт перемещений точный; ошибки навигации — будущая идея.'],
 'metric-facing':['Взгляд','Направление в собственной системе отсчёта. После успешного шага организм смотрит в сторону движения. Собственный поворот при рождении не раскрывает глобальный компас.'],
 'metric-inventory':['Еда при себе','Количество целых порций в инвентаре, до трёх. Подбор не насыщает: нужно действие «съесть», затем пищеварение. Действие «Положить» переносит одну порцию на текущую сушу за3 подшага и0,108 энергии (плюс цена решения), если там меньше 10 порций. Еду может подобрать любой житель. Пища вне источника сама не восстанавливается; готовой цели копить запас нет.'],
 'metric-stomach':['Пищеварение','Съеденная пища усваивается со следующего шага по 1.1 энергии за шаг. Порция содержит 22 энергии; вместимость — три порции.'],
 'metric-action':['Последнее действие','Последний исполненный примитив: один из шести шагов, подобрать, съесть, ждать, родить или положить одну порцию. Встроенных целей «искать еду» или «мигрировать» нет.'],
 'analysis-file-a':['Загрузить геном A','Локально читает JSON генома v12, v11 либо прежних v1–v9 (v10 несовместим), до 100 КБ. TXT с тем же JSON тоже допустим. Файл не отправляется на сервер, не становится основой мира и не запускает симуляцию. Нужен именно экспорт генома, не отчёт испытаний или история.'],
 'analysis-file-b':['Загрузить геном B','Второй независимый файл добавляет сравнение B − A. Можно загрузить только B для одиночного разбора. Разные версии сравниваются по смыслу, отсутствующее действие не заменяется нулём.'],
 'analysis-clear-a':['Очистить A','Убирает только файл A из анализа; мир и файл B сохраняются. Отменяет результат ещё не завершившегося чтения A.'],
 'analysis-clear-b':['Очистить B','Убирает только файл B из анализа; мир и файл A сохраняются.'],
 'analysis-view':['Свойства выбранного файла','Переключает расшифровку A/B. В таблице есть оригинальный индекс с нуля, сырое число и пересчитанный параметр. Отсутствующие в старой версии свойства не подставляются.'],
 'analysis-policy-view':['Базовые оценки или разности','Для старых геномов показывает таблицу, для сети — подписанные связи/смещения; B − A сравнивает только совместимые параметры. Это не реальные вероятности действий: физическая доступность, окружение и личные оценки отсутствуют. Неизвестное кодирование состояния ограничивает сравнение.'],
 'analysis-energy':['Фильтр строк','Оставляет строки с выбранной условной энергией. Фильтр не меняет геном и не создаёт тело. При неизвестном кодировании состояния фильтр отключён. Скачиваемый анализ содержит все 48 строк.'],
 'analysis-export-json':['Скачать полный анализ','Сохраняет свойства, исходные индексы, подписи действий, все строки таблицы и разности B − A. Это производный отчёт, не геном для импорта и не сохранение мира. Исходные файлы держи отдельно.'],
 'analysis-export-md':['Скачать пояснения','Короткий Markdown с параметрами, интерпретацией и ограничениями; его можно прислать для обсуждения. Полная матрица остаётся в JSON анализа. Напечатанные числа округлены, JSON хранит исходную точность.'],
 'retry-check':['Повторить проверку','Повторяет конкретную изолированную проверку. Предыдущие попытки остаются в отчёте, чтобы ошибка не исчезала бесследно.'],
};
export const ALIASES={'test-founders':'founders','test-limit':'population-limit','test-geography':'geography','test-mutations':'mutations','test-food-sources':'food-sources','test-food-period':'food-period','test-food-islands':'food-islands','test-food-period-spread':'food-period-spread','test-food-size-spread':'food-size-spread','world-food-islands':'food-islands','world-food-period-spread':'food-period-spread','world-food-size-spread':'food-size-spread','history-next':'history-prev'};
export function createHelpButton(key){
 const button=document.createElement('button');button.type='button';button.className='help-trigger';button.dataset.help=ALIASES[key]??key;
 button.textContent='?';button.setAttribute('aria-label',`Подсказка: ${HELP[button.dataset.help][0]}`);button.setAttribute('aria-haspopup','dialog');button.setAttribute('aria-controls','help-dialog');return button;
}
export function installHelp(pauseWorld){
 const dialog=document.getElementById('help-dialog'),title=document.getElementById('help-title'),body=document.getElementById('help-body');let opener=null;
 for(const [id,key]of [...Object.keys(HELP).map(id=>[id,id]),...Object.entries(ALIASES)]){
  const control=document.getElementById(id);if(!control)continue;
  // Кнопка помощи — сосед label, а не интерактивный элемент внутри него:
  // нажатие вопроса не должно переключать checkbox или активировать действие.
  const label=control.closest('label');
  if(label||control.tagName==='BUTTON'){
   const target=label??control,wrapper=document.createElement('div');wrapper.className='help-control'+(label?'':' help-action');target.before(wrapper);wrapper.append(target,createHelpButton(key));
  }else if(['population','births','deaths','generation','lineages'].includes(id))control.parentElement.querySelector('small').append(createHelpButton(key));
  else{
   const wrapper=document.createElement('div');wrapper.className='help-explained';
   control.before(wrapper);wrapper.append(control,createHelpButton(key));
  }
 }
 document.addEventListener('click',event=>{
  const button=event.target.closest?.('[data-help]');if(!button)return;
  event.preventDefault();event.stopPropagation();const entry=HELP[button.dataset.help];if(!entry)return;
  opener=button;pauseWorld();title.textContent=entry[0];body.textContent=entry[1];dialog.showModal();
 });
 document.getElementById('help-close').addEventListener('click',()=>dialog.close());
 dialog.addEventListener('click',event=>{if(event.target===dialog){const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)dialog.close();}});
 dialog.addEventListener('close',()=>{
  // Панель тела обновляется при паузе. Если её прежняя кнопка уже заменена,
  // возвращаем фокус на новую кнопку той же подсказки, а не на исчезнувший узел.
  const fallback=[...document.querySelectorAll('[data-help]')].find(b=>b.dataset.help===opener?.dataset.help&&!b.closest('[hidden]'));
  (opener?.isConnected?opener:fallback)?.focus();
 });
}
